try{life();console.log('KIT_START',JSON.stringify(bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed])));bot.clearControlStates();bot.deactivateItem();await ticks(4);if(bot.entity.position.distanceTo(q.offset(.5,0,.5))>.65||!(tunnelSafe(q)||shell(q)))throw Error('START_NOT_SEALED');guard();bot.chat('P1 bounded128 WESTRODcourier BRICKfloor only, BLAZEexposure explicit/shieldfacingnearest, HP17stop/fullending: freshhazardguards, exactclosurebudget+2, actualfloor/arrival then fullendpoint or fallback: INTERMEDIATEtravel EXPOSED underfreshhazardguards; consumesmaterials; ENDING requiresactualfullpersonalroom+settledbody, notwholecorridor.');
 const proposal=global.P1GroundProposal;if(!proposal||proposal.origin.some((v,k)=>v!==[q.x,q.y,q.z][k]))throw Error('STALE_PROPOSAL');console.log('CONSUMED_PROPOSAL',proposal.when,JSON.stringify(proposal));const planned=proposal.path.slice(1,MAX+1);for(let k=0;k<planned.length;k++){if(Date.now()-started>140000){console.log("NATURAL_BUDGET_STOP",k);break;}const n=new Vec3(...planned[k]);if(Math.abs(n.y-current.y)>1||Math.abs(n.x-current.x)+Math.abs(n.z-current.z)!==1)throw Error('NONCARDINAL_PROPOSAL');dir=new Vec3(n.x-current.x,0,n.z-current.z);const stepY=n.y-current.y;if(stepY===1&&bot.blockAt(current.offset(0,2,0))?.boundingBox!=='empty')throw Error('UP_SOURCE_HEAD_CHANGED');if(stepY===-1&&bot.blockAt(n.offset(0,2,0))?.boundingBox!=='empty')throw Error('DOWN_HEAD_CHANGED');envelopeFoot=n;nextFoot=n;dryScan(n);guard();const needed=closeNeed(n);console.log('BRIDGE_CLOSURE_BUDGET',n.toString(),needed,mats());if(mats()<needed+2){console.log('BRIDGE_RESERVE_STOP');break;}for(const y of[1,0]){const b=bot.blockAt(n.offset(0,y,0));if(b.boundingBox!=='empty'){await dig(b);opened=true;}}await put(n.offset(0,-1,0),current.offset(0,-1,0),dir);if(!cold(n))throw Error("OPEN_TARGET_POST");await go(n);opened=true;current=n;trace.push(n);if(!cellSet.has(n.toString())){cells.push(n);cellSet.add(n.toString());}}
 await sealCurrent();global.P1Tunnel=null;for(const name of['nether_bricks','spawner','chest','warped_nylium'])console.log('LOADED_RESOURCE',name,bot.findBlocks({matching:bot.registry.blocksByName[name].id,maxDistance:160,count:8}).map(p=>p.toString()));
}finally{try{if(!dead&&bot.game.dimension==='the_nether'&&!adopted){try{await go(current,true);if(tunnelSafe(current))await acceptTunnel();else {await sealCurrent();global.P1Tunnel=null;}}catch(error){console.log('ADOPT_FAILED_TRY_ORIGIN',error.message);for(const p of trace.slice().reverse())await go(p,true);current=q;await sealCurrent();}}}finally{bot.pathfinder.setGoal(null);bot.clearControlStates();bot.removeListener('death',die);bot.removeListener('respawn',die);bot.removeListener('end',die);if(!dead&&bot.game.dimension==='the_nether'){const a=bot.inventory.items().find(i=>i.name==='stone_axe');if(a){await bot.equip(a,'hand');await bot.waitForTicks(4);bot.activateItem(true)}}console.log('FINAL',bot.entity.position.toString(),bot.game.dimension,bot.health,bot.food,'dead',dead,'adopted',adopted);}}
